#!/usr/bin/env node
// Brand registry: validates brands/*/brand.json and generates core/remotion/src/lib/brands.generated.ts.
// Adding a brand = create brands/<id>/brand.json, run `npm run brands` (or it runs in `npm run check`). No code edits.
//   node scripts/brands.mjs          validate + write the generated file
//   node scripts/brands.mjs --check  validate + fail if the generated file is stale (used by tests / CI)
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const BRANDS = path.join(ROOT, "brands");
const OUT = path.join(ROOT, "core/remotion/src/lib/brands.generated.ts");
const FONTS = ["Readex Pro", "Space Grotesk", "JetBrains Mono"]; // bundled in core/remotion/public/fonts
const COLOR_KEYS = ["background", "surface", "primary", "secondary", "accent", "text", "onMedia", "muted"];
const REQUIRED_WHEN_READY = ["background", "primary", "secondary", "accent"];
const STATUSES = ["ready", "draft", "needs-input"];
const COLOR_RE = /^(#[0-9a-fA-F]{3}|#[0-9a-fA-F]{6}|#[0-9a-fA-F]{8}|rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*(,\s*(0|1|0?\.\d+)\s*)?\))$/;

export function validateBrand(id, b) {
  const errors = [], warnings = [];
  if (!b || typeof b !== "object") return { errors: ["not a JSON object"], warnings };
  if (b.id !== id) errors.push(`id "${b.id}" must equal folder name "${id}"`);
  for (const k of ["name", "nameAr"]) if (typeof b[k] !== "string" || !b[k].trim()) errors.push(`${k} must be a non-empty string`);
  if (!STATUSES.includes(b.status)) errors.push(`status must be one of ${STATUSES.join(", ")}`);
  if (!b.colors || typeof b.colors !== "object") errors.push("colors object missing");
  else {
    for (const k of Object.keys(b.colors)) if (!COLOR_KEYS.includes(k)) errors.push(`unknown colour key "${k}" (allowed: ${COLOR_KEYS.join(", ")})`);
    for (const [k, v] of Object.entries(b.colors)) if (v !== null && (typeof v !== "string" || !COLOR_RE.test(v))) errors.push(`colors.${k} "${v}" is not a valid hex/rgba colour`);
    if (b.status === "ready") for (const k of REQUIRED_WHEN_READY) if (!b.colors[k]) errors.push(`status "ready" requires colors.${k}`);
    if (b.status !== "ready" && REQUIRED_WHEN_READY.some((k) => !b.colors[k])) warnings.push(`missing ${REQUIRED_WHEN_READY.filter((k) => !b.colors[k]).join(", ")} → studio defaults are used`);
  }
  if (b.gradient !== undefined && b.gradient !== null) {
    if (!Array.isArray(b.gradient) || b.gradient.length < 2 || b.gradient.some((c) => !COLOR_RE.test(String(c)))) errors.push("gradient must be an array of ≥2 valid colours or null");
  }
  if (b.links !== undefined && b.links !== null) {
    if (typeof b.links !== "object" || Array.isArray(b.links)) errors.push("links must be an object like {\"web\": \"lef.one\", \"tiktok\": \"@lef.one\"}");
    else for (const [k, v] of Object.entries(b.links)) if (typeof v !== "string" || !v.trim()) errors.push(`links.${k} must be a non-empty string`);
  }
  if (b.fonts) for (const [k, f] of Object.entries(b.fonts)) if (!FONTS.includes(f)) errors.push(`fonts.${k} "${f}" is not bundled (available: ${FONTS.join(", ")})`);
  if (b.logo) {
    if (typeof b.logo !== "string") errors.push("logo must be a path string or null");
    else if (!fs.existsSync(path.join(BRANDS, id, b.logo))) warnings.push(`logo file ${b.logo} not present locally (assets are git-ignored)`);
  } else warnings.push("no approved logo yet");
  return { errors, warnings };
}

export function loadAll() {
  const out = {}, report = [];
  for (const id of fs.readdirSync(BRANDS).sort()) {
    const f = path.join(BRANDS, id, "brand.json");
    if (!fs.statSync(path.join(BRANDS, id)).isDirectory() || !fs.existsSync(f)) continue;
    let b;
    try { b = JSON.parse(fs.readFileSync(f, "utf8")); } catch (e) { report.push({ id, errors: [`invalid JSON: ${e.message}`], warnings: [] }); continue; }
    const r = validateBrand(id, b);
    report.push({ id, ...r });
    if (!r.errors.length) out[id] = b;
  }
  return { brands: out, report };
}

export function render(brands) {
  const pick = (b) => ({ id: b.id, name: b.name, nameAr: b.nameAr, status: b.status, colors: b.colors, gradient: b.gradient ?? null, fonts: b.fonts ?? {}, logo: b.logo ?? null, links: b.links ?? null });
  const data = Object.fromEntries(Object.entries(brands).map(([k, v]) => [k, pick(v)]));
  return `// AUTO-GENERATED by scripts/brands.mjs from brands/*/brand.json — do not edit by hand.\n` +
    `import type { RawBrand } from "./brandResolve";\n\nexport const RAW_BRANDS: Record<string, RawBrand> = ${JSON.stringify(data, null, 2)};\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const { brands, report } = loadAll();
  let bad = false;
  for (const r of report) {
    const tag = r.errors.length ? "✘" : r.warnings.length ? "•" : "✔";
    console.log(`${tag} ${r.id}${r.errors.length ? "  " + r.errors.join("; ") : ""}${r.warnings.length ? "  (" + r.warnings.join("; ") + ")" : ""}`);
    if (r.errors.length) bad = true;
  }
  if (!brands.studio) { console.error("✘ brands/studio is required (fallback brand)"); bad = true; }
  const next = render(brands);
  if (process.argv.includes("--check")) {
    const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
    if (cur !== next) { console.error("✘ brands.generated.ts is stale: run `npm run brands`"); bad = true; }
  } else if (!bad) fs.writeFileSync(OUT, next);
  process.exit(bad ? 1 : 0);
}
